// dsh-skill-manager-ytxue client half: 设置侧边栏「Skill 管理」面板（AMD bundle，__ModuleLoader__ 格式）
// 仅在浏览器中执行，Node 环境跳过
if (typeof window !== 'undefined') {

  window.__ModuleLoader__.load({
    id: "dsh-skill-manager-ytxue",
    factory: (require) => {
      var module = { exports: {} };
      var exports = module.exports;
      Object.defineProperty(exports, Symbol.toStringTag, { value: "Module" });
      var react = require("react");
      var h = react.createElement;

      // ---- 样式注入（官方 data-plugin-css 模式）----
      var CSS_ID = "dsh-skill-manager-ytxue/section.css";
      var cssText = [
        ".dskm-section{max-width:720px;flex-direction:column;gap:12px;color:var(--dsw-alias-label-primary);display:flex}",
        ".dskm-block{flex-direction:column;gap:8px;display:flex}",
        ".dskm-title{margin:0;font-size:16px;font-weight:500;line-height:24px}",
        ".dskm-sub{color:var(--dsw-alias-label-tertiary);margin:0;font-size:12px;line-height:18px}",
        ".dskm-row{border:1px solid var(--dsw-alias-border-l2);border-radius:12px;align-items:center;gap:10px;padding:10px 12px;display:flex}",
        ".dskm-dot{flex:none;width:8px;height:8px;border-radius:50%;display:inline-block}",
        ".dskm-dot-ok{background:var(--dsw-alias-state-success-primary)}",
        ".dskm-dot-pending{background:var(--dsw-alias-state-error-primary)}",
        ".dskm-dot-none{background:var(--dsw-alias-label-tertiary)}",
        ".dskm-row-scope{color:var(--dsw-alias-state-info-primary,var(--dsw-alias-label-secondary))}",
        ".dskm-row-main{flex-direction:column;gap:2px;min-width:0;flex:1;display:flex}",
        ".dskm-row-id{align-items:center;gap:6px;min-width:0;display:inline-flex}",
        ".dskm-row-name{font-size:14px;font-weight:500;line-height:22px}",
        ".dskm-desc{color:var(--dsw-alias-label-tertiary);font-size:12px;line-height:18px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}",
        ".dskm-row-tag{border:1px solid var(--dsw-alias-border-l3);color:var(--dsw-alias-label-secondary);border-radius:4px;flex:none;padding:1px 6px;font-size:11px;line-height:16px}",
        ".dskm-btn{box-sizing:border-box;height:30px;border:none;border-radius:15px;justify-content:center;align-items:center;gap:4px;margin-left:auto;padding:0 12px;font-family:inherit;font-size:13px;line-height:20px;cursor:pointer;display:inline-flex;background:var(--dsw-alias-button-primary-fill);color:var(--dsw-alias-label-primary-foreground)}",
        ".dskm-btn:disabled{opacity:.5;cursor:default}",
        ".dskm-btn-secondary{background:transparent;border:1px solid var(--dsw-alias-border-l3);color:var(--dsw-alias-label-secondary)}",
        ".dskm-error{color:var(--dsw-alias-state-error-primary);font-size:13px;line-height:20px}",
        ".dskm-note{color:var(--dsw-alias-label-tertiary);font-size:12px;line-height:18px}",
        ".dskm-empty{color:var(--dsw-alias-label-tertiary);font-size:13px;line-height:20px;padding:2px}",
        ".dskm-block-head{flex:none;align-items:center;gap:8px;display:flex}",
        ".dskm-head-actions{justify-content:flex-end;align-items:center;gap:8px;margin-left:auto;display:flex}",
        ".dskm-picker-confirm{height:28px;border-radius:14px;padding:0 10px;font-size:13px}",
        ".dskm-picker-up{height:28px;border-radius:14px;padding:0 10px;font-size:13px}",
        ".dskm-import-row{flex-direction:row;gap:8px;display:flex}",
        ".dskm-input{box-sizing:border-box;height:32px;flex:1;min-width:0;border:1px solid var(--dsw-alias-border-l2);border-radius:8px;background:transparent;color:var(--dsw-alias-label-primary);padding:0 10px;font-family:inherit;font-size:13px}",
        ".dskm-input-wrap{box-sizing:border-box;position:relative;flex:1;min-width:0;display:flex}",
        ".dskm-input-wrap .dskm-input{padding-right:34px}",
        ".dskm-input-browse{box-sizing:border-box;position:absolute;right:3px;top:50%;transform:translateY(-50%);cursor:pointer;border:none;border-radius:6px;background:transparent;color:var(--dsw-alias-label-secondary);font-size:14px;line-height:1;padding:4px 6px}",
        ".dskm-input-browse:hover{background:var(--dsw-alias-interactive-bg-hover)}",
        ".dskm-input-browse:disabled{opacity:.5;cursor:default}",
        ".dskm-import-target{flex-direction:column;gap:4px;display:flex;font-size:13px;line-height:20px}",
        ".dskm-radio{cursor:pointer;display:inline-flex;align-items:center;gap:6px;color:var(--dsw-alias-label-secondary)}",
        ".dskm-picker-mask{z-index:1100;justify-content:center;align-items:center;background:var(--dsw-alias-bg-mask-1);display:flex;position:fixed;inset:0}",
        ".dskm-picker{box-sizing:border-box;background:var(--dsw-alias-bg-layer-2);width:min(560px,92vw);max-height:70vh;flex-direction:column;gap:8px;border:1px solid var(--dsw-alias-border-l2);border-radius:16px;padding:16px;display:flex;box-shadow:var(--dsw-shadow-lv3)}",
        ".dskm-picker-head{flex:none;align-items:center;gap:8px;display:flex}",
        ".dskm-picker-title{flex:1;color:var(--dsw-alias-label-primary);font-size:15px;font-weight:500}",
        ".dskm-picker-close{box-sizing:border-box;cursor:pointer;border:none;border-radius:14px;background:0 0;color:var(--dsw-alias-label-secondary);font-family:inherit;font-size:13px;padding:4px 8px}",
        ".dskm-picker-path{flex:none;border:1px solid var(--dsw-alias-border-l2);border-radius:8px;color:var(--dsw-alias-label-secondary);padding:6px 10px;font-size:12px;line-height:18px;word-break:break-all}",
        ".dskm-picker-list{flex:1 1 0;min-height:260px;flex-direction:column;gap:2px;padding:4px;display:flex;overflow-y:auto}",
        ".dskm-picker-row{box-sizing:border-box;cursor:pointer;border-radius:6px;align-items:center;padding:4px 8px;font-size:13px;line-height:20px;display:flex;color:var(--dsw-alias-label-primary)}",
        ".dskm-picker-row:hover{background:var(--dsw-alias-interactive-bg-hover)}",
        ".dskm-picker-dir{color:var(--dsw-alias-label-primary)}",
        ".dskm-picker-file{color:var(--dsw-alias-label-tertiary);cursor:default}",
        ".dskm-picker-foot{flex:none;justify-content:flex-end;align-items:center;gap:8px;display:flex}",
        ".dskm-issue{font-size:12px;line-height:18px}",
        ".dskm-issue-error{color:var(--dsw-alias-state-error-primary)}",
        ".dskm-issue-warning{color:var(--dsw-alias-state-warn-label)}",
        ".dskm-ok{color:var(--dsw-alias-state-success-primary);font-size:12px;line-height:18px}"
      ].join("");
      if (typeof document !== "undefined" && document.querySelector('style[data-plugin-css="' + CSS_ID + '"]') === null) {
        var tag = document.createElement("style");
        tag.dataset.plugin = "dsh-skill-manager-ytxue";
        tag.dataset.pluginCss = CSS_ID;
        tag.textContent = cssText;
        document.head.appendChild(tag);
      }

      // ---- API 调用 ----
      // 响应统一 {ok, data?} / {ok:false, error}；无 data 字段的操作响应（如 enable/disable）直接返回整个对象
      function callApi(path, options) {
        return fetch("/api/skill-manager-ytxue" + path, options)
          .then(function (r) { return r.json().then(function (j) { if (!j.ok) throw new Error(j.error || ("HTTP " + r.status)); return j.data !== undefined ? j.data : j; }); });
      }

      // ---- 面板组件 ----
      function SkillManagerSection() {
        var state = react.useState({ loading: true, error: null, data: null });
        var snapshot = state[0];
        var setSnapshot = state[1];
        var stateBusy = react.useState(null);
        var busy = stateBusy[0];
        var setBusy = stateBusy[1];
        var stateReport = react.useState(null);
        var report = stateReport[0];
        var setReport = stateReport[1];
        var stateImportPath = react.useState("");
        var importPath = stateImportPath[0];
        var setImportPath = stateImportPath[1];
        var stateImportTarget = react.useState("skills");
        var importTarget = stateImportTarget[0];
        var setImportTarget = stateImportTarget[1];
        var stateImportResult = react.useState(null);
        var importResult = stateImportResult[0];
        var setImportResult = stateImportResult[1];
        var statePicker = react.useState({ open: false, path: "", entries: [], error: null, loading: false });
        var picker = statePicker[0];
        var setPicker = statePicker[1];
        var stateConfirm = react.useState(null); // {source, target, pending, conflicts, failed}
        var confirmImport = stateConfirm[0];
        var setConfirmImport = stateConfirm[1];

        react.useEffect(function () {
          var alive = true;
          callApi("/state?cwd=" + encodeURIComponent(currentCwd || ""))
            .then(function (d) { if (alive) setSnapshot({ loading: false, error: null, data: d }); })
            .catch(function (e) { if (alive) setSnapshot({ loading: false, error: String((e && e.message) || e), data: null }); });
          return function () { alive = false; };
        }, []);

        function refresh() {
          setSnapshot({ loading: true, error: null, data: snapshot.data });
          callApi("/state?cwd=" + encodeURIComponent(currentCwd || ""))
            .then(function (d) { setSnapshot({ loading: false, error: null, data: d }); })
            .catch(function (e) { setSnapshot({ loading: false, error: String((e && e.message) || e), data: snapshot.data }); });
        }

        function act(path, body) {
          if (busy) return;
          setBusy(path);
          callApi(path, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body || {}) })
            .then(function () { setBusy(null); refresh(); })
            .catch(function (e) { setBusy(null); setSnapshot({ loading: false, error: String((e && e.message) || e), data: snapshot.data }); });
        }

        function runCheck() {
          if (busy) return;
          setBusy("check");
          setReport(null);
          callApi("/check", { method: "POST" })
            .then(function (d) { setBusy(null); setReport(d); refresh(); })
            .catch(function (e) { setBusy(null); setReport({ error: String((e && e.message) || e) }); });
        }

        // ---- 目录选择器 ----
        function loadPicker(path) {
          setPicker({ open: true, path: picker.path, entries: [], count: undefined, error: null, loading: true });
          callApi("/list-dir?path=" + encodeURIComponent(path || ""))
            .then(function (d) { setPicker({ open: true, path: d.path, entries: d.entries || [], count: d.count, error: null, loading: false }); })
            .catch(function (e) { setPicker({ open: true, path: path, entries: [], count: undefined, error: String((e && e.message) || e), loading: false }); });
        }
        function openPicker() { setPicker({ open: true, path: "__drives__", entries: [], error: null, loading: true }); loadPicker("__drives__"); }
        function pickerEnter(name) {
          // 此电脑视图：点盘符进入盘根（如 D: -> D:\）
          if (picker.path === "__drives__") { loadPicker(name.replace(/[\\/]+$/, "") + "\\"); return; }
          var next = picker.path.replace(/[\\/]+$/, "") + "\\" + name;
          loadPicker(next);
        }
        function pickerUp() {
          var p = picker.path;
          if (!p || p === "__drives__") return;
          p = p.replace(/[\\/]+$/, "");
          if (/^[A-Za-z]:$/.test(p)) { loadPicker("__drives__"); return; } // 盘根 -> 此电脑
          var idx = Math.max(p.lastIndexOf("\\"), p.lastIndexOf("/"));
          loadPicker(idx > 0 ? p.slice(0, idx + 1) : "__drives__");
        }
        function pickerConfirm() {
          if (!picker.path || picker.loading || picker.path === "__drives__") return;
          setImportPath(picker.path);
          setPicker({ open: false, path: "", entries: [], error: null, loading: false });
        }
        function pickerCancel() {
          setPicker({ open: false, path: "", entries: [], error: null, loading: false });
        }

        // 导入：先预检（dryRun），发现重名则弹窗询问（跳过/覆盖，同系统重名文件逻辑）
        function executeImport(src, conflict, target) {
          setBusy("import");
          setConfirmImport(null);
          callApi("/import", {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({ source: src, target: target, conflict: conflict })
          })
            .then(function (d) {
              setBusy(null);
              setImportResult(d); // {kind, imported, skipped, failed}
              setImportPath("");
              refresh();
              if (target === "skills" && d && d.imported && d.imported.length) runCheck(); // 导入到启用目录后自动检查
            })
            .catch(function (e) {
              setBusy(null);
              setImportResult({ error: String((e && e.message) || e) });
            });
        }
        function doImport() {
          if (busy) return;
          var src = (importPath || "").trim();
          if (!src) {
            setImportResult({ error: "请先填写路径，或点击「选择文件夹…」" });
            return;
          }
          setBusy("import");
          setImportResult(null);
          callApi("/import", {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({ source: src, target: importTarget, dryRun: true })
          })
            .then(function (d) {
              if (d.conflicts && d.conflicts.length) {
                setBusy(null);
                setConfirmImport({ source: src, target: importTarget, pending: d.pending || [], conflicts: d.conflicts, failed: d.failed || [] });
                return;
              }
              executeImport(src, "skip", importTarget);
            })
            .catch(function (e) {
              setBusy(null);
              setImportResult({ error: String((e && e.message) || e) });
            });
        }

        function row(item, actionLabel, secondary, action, scopeLabel) {
          var checked = !!item.checked;
          var isProject = item.scope === "project";
          // 红绿点仅对参与规范检查的用户级条目有意义；项目级条目显示灰点（只读，不参与检查）
          var dot = isProject
            ? h("span", { className: "dskm-dot dskm-dot-none", title: "项目级 skill，只读展示，不参与规范检查" })
            : h("span", {
              className: "dskm-dot " + (checked ? "dskm-dot-ok" : "dskm-dot-pending"),
              title: checked ? "规范已检查（内容未变）" : "尚未检查规范"
            });
          return h("div", { key: item.name, className: "dskm-row" },
            dot,
            h("div", { className: "dskm-row-main" },
              h("div", { className: "dskm-row-id" },
                h("span", { className: "dskm-row-name" }, item.name),
                h("span", {
                  className: "dskm-row-tag",
                  title: item.kind === "bundle"
                    ? "目录 bundle：<name>/SKILL.md，可含脚本/模板等多文件"
                    : "平铺：<name>.md，单文件 skill"
                }, item.kind === "bundle" ? "bundle" : "flat"),
                scopeLabel
                  ? h("span", {
                    className: "dskm-row-tag dskm-row-scope",
                    title: scopeLabel === "系统级"
                      ? "用户级：~/.dsh/skills（对全部项目生效）"
                      : "项目级：<项目根>/.dsh/skills 或 .agents/skills（仅该项目生效）"
                  }, scopeLabel)
                  : null),
              h("div", { className: "dskm-desc", title: item.description || "" }, item.description || "（无简介）")),
            actionLabel
              ? h("button", {
                className: "dskm-btn" + (secondary ? " dskm-btn-secondary" : ""),
                disabled: !!busy,
                onClick: action
              }, actionLabel)
              : null);
        }

        var nodes = [];
        if (snapshot.loading && !snapshot.data) {
          nodes.push(h("div", { key: "loading", className: "dskm-note" }, "加载中…"));
        }
        if (snapshot.error) {
          nodes.push(h("div", { key: "error", className: "dskm-error" }, "错误: " + snapshot.error));
        }
        if (snapshot.data) {
          var enabled = snapshot.data.enabled || [];
          var pool = snapshot.data.pool || [];
          nodes.push(h("div", { key: "enabled", className: "dskm-block" },
            h("div", { className: "dskm-block-head" },
              h("h3", { className: "dskm-title" }, "已启用（系统级 · 原生扫描）"),
              h("div", { className: "dskm-head-actions" },
                h("button", { className: "dskm-btn dskm-btn-secondary", disabled: !!busy, onClick: refresh }, "刷新"),
                h("button", { className: "dskm-btn", disabled: !!busy, onClick: runCheck }, busy === "check" ? "检查中…" : "一键检查"))),
            enabled.length === 0
              ? h("div", { className: "dskm-empty" }, "（空）")
              : enabled.map(function (it) { return row(it, "停用", true, function () { act("/disable", { name: it.name }); }, "系统级"); })));
          var projects = snapshot.data.projects || [];
          projects.forEach(function (proj, pi) {
            nodes.push(h("div", { key: "proj" + pi, className: "dskm-block" },
              h("h3", { className: "dskm-title", title: proj.root }, "项目级 Skill" + (proj.current ? "（当前项目）" : "（配置）") + " · " + proj.root),
              (proj.items || []).length === 0
                ? h("div", { className: "dskm-empty" }, "（该项目无 .dsh/skills 或 .agents/skills 条目）")
                : proj.items.map(function (it) { return row(it, null, false, null, "项目级"); })));
          });
          nodes.push(h("div", { key: "pool", className: "dskm-block" },
            h("h3", { className: "dskm-title" }, "池（未挂载，按需启用）"),
            pool.length === 0
              ? h("div", { className: "dskm-empty" }, "（空）")
              : pool.map(function (it) { return row(it, "启用", false, function () { act("/enable", { name: it.name }); }); })));
          nodes.push(h("div", { key: "import", className: "dskm-block" },
            h("h3", { className: "dskm-title" }, "导入 Skill"),
            h("p", { className: "dskm-sub" }, "选择或填写本机 skill 路径。单个 skill 目录（含 SKILL.md）→ 导入 1 个；包含多个 skill 的大文件夹 → 自动逐个导入。导入时自动规整 kebab-case，重名不覆盖。"),
            h("div", { className: "dskm-import-row" },
              h("div", { className: "dskm-input-wrap" },
                h("input", {
                  className: "dskm-input",
                  type: "text",
                  value: importPath,
                  placeholder: "路径，或点击右侧图标选择文件夹",
                  onChange: function (e) { setImportPath(e.target.value); }
                }),
                h("button", { className: "dskm-input-browse", disabled: !!busy, title: "选择文件夹", onClick: openPicker }, "📂")),
              h("button", { className: "dskm-btn", disabled: !!busy, onClick: doImport }, busy === "import" ? "导入中…" : "导入")),
            h("div", { className: "dskm-import-target" },
              h("label", { className: "dskm-radio" },
                h("input", { type: "radio", name: "import-target", checked: importTarget === "skills", onChange: function () { setImportTarget("skills"); } }),
                "复制到启用目录 skills\\（立即生效，导入后自动检查）"),
              h("label", { className: "dskm-radio" },
                h("input", { type: "radio", name: "import-target", checked: importTarget === "pool", onChange: function () { setImportTarget("pool"); } }),
                "复制到池 skill-pool\\（零挂载，之后按需启用）")),
            importResult
              ? (importResult.error
                ? h("div", { className: "dskm-error" }, "导入失败: " + importResult.error)
                : h("div", { className: "dskm-block" },
                  h("div", { className: "dskm-note" }, "导入完成：" + (importResult.imported || []).length + " 个成功"
                    + ((importResult.skipped || []).length ? "，" + importResult.skipped.length + " 个重名已跳过" : "")
                    + ((importResult.failed || []).length ? "，" + importResult.failed.length + " 个失败" : "")),
                  (importResult.imported || []).map(function (it, i) {
                    return h("div", { key: "ok" + i, className: "dskm-ok" },
                      "✓ " + it.name + (it.overwritten ? "（已覆盖原有）" : "") + (it.warnings && it.warnings.length ? " ⚠ " + it.warnings.join("；") : ""));
                  }),
                  (importResult.skipped || []).map(function (it, i) {
                    return h("div", { key: "sk" + i, className: "dskm-issue dskm-issue-warning" }, "△ " + it.name + "（重名，已跳过）");
                  }),
                  (importResult.failed || []).map(function (it, i) {
                    return h("div", { key: "no" + i, className: "dskm-error" }, "✗ " + it.source + "：" + it.error);
                  })))
              : null));
          nodes.push(h("div", { key: "audit", className: "dskm-block" },
            h("h3", { className: "dskm-title" }, "DSH 规范检查"),
            h("p", { className: "dskm-sub" }, "● 绿点 = 规范已检查且内容未变；红点 = 尚未检查或内容已变更。一键检查只处理红点条目，已检查的自动跳过；不合规项自动修复并记录到 skill-manager-ytxue.log。")));
        }
        if (report) {
          var rn = [];
          if (report.error) rn.push(h("div", { key: "e", className: "dskm-error" }, "检查失败: " + report.error));
          else {
            rn.push(h("div", { key: "sum", className: "dskm-note" }, "检查 " + (report.checked || []).length + " 个（未检查项），跳过 " + (report.skipped || []).length + " 个（已检查），修复 " + (report.fixed || []).length + " 处"));
            (report.fixed || []).forEach(function (f, i) {
              rn.push(h("div", { key: "f" + i, className: "dskm-ok" }, "✓ " + f.name + ": " + f.detail));
            });
            (report.checked || []).forEach(function (c, i) {
              (c.issues || []).forEach(function (iss, j) {
                rn.push(h("div", {
                  key: "i" + i + "-" + j,
                  className: "dskm-issue " + (iss.severity === "error" ? "dskm-issue-error" : "dskm-issue-warning")
                }, (iss.severity === "error" ? "✗ " : "△ ") + c.name + ": " + iss.message));
              });
            });
            if ((report.fixed || []).length === 0 && (report.checked || []).every(function (c) { return (c.issues || []).length === 0; })) {
              rn.push(h("div", { key: "all", className: "dskm-ok" }, "✓ 全部条目符合 DSH 规范"));
            }
          }
          nodes.push(h("div", { key: "report", className: "dskm-block" }, rn));
        }
        // ---- 重名询问对话框（同系统重名文件逻辑）----
        if (confirmImport) {
          nodes.push(h("div", { key: "confirm", className: "dskm-picker-mask" },
            h("div", { className: "dskm-picker" },
              h("div", { className: "dskm-picker-head" },
                h("span", { className: "dskm-picker-title" }, "发现重名 Skill")),
              h("div", { className: "dskm-picker-path" },
                "将导入 " + (confirmImport.pending || []).length + " 个，" + (confirmImport.conflicts || []).length + " 个与现有条目重名：" + (confirmImport.conflicts || []).map(function (c) { return c.name; }).join("、")),
              h("div", { className: "dskm-note" }, "请选择处理方式："),
              h("div", { className: "dskm-picker-foot" },
                h("button", { className: "dskm-btn dskm-btn-secondary", disabled: !!busy, onClick: function () { setConfirmImport(null); } }, "取消"),
                h("button", { className: "dskm-btn dskm-btn-secondary", disabled: !!busy, onClick: function () { executeImport(confirmImport.source, "skip", confirmImport.target); } }, "跳过重名并导入其余"),
                h("button", { className: "dskm-btn", disabled: !!busy, onClick: function () { executeImport(confirmImport.source, "overwrite", confirmImport.target); } }, "覆盖重名（替换现有）")))));
        }
        // ---- 目录选择对话框 ----
        if (picker.open) {
          nodes.push(h("div", { key: "picker", className: "dskm-picker-mask" },
            h("div", { className: "dskm-picker" },
              h("div", { className: "dskm-picker-head" },
                h("span", { className: "dskm-picker-title" }, "选择文件夹"),
                h("button", { className: "dskm-btn dskm-btn-secondary dskm-picker-up", disabled: picker.loading || !picker.path || picker.path === "__drives__", onClick: pickerUp }, "返回上级文件夹"),
                h("button", { className: "dskm-btn dskm-btn-secondary dskm-picker-confirm", disabled: picker.loading || !picker.path || picker.path === "__drives__", onClick: pickerConfirm }, "选择此文件夹"),
                h("button", { className: "dskm-btn-secondary dskm-picker-close", onClick: pickerCancel }, "✕")),
              h("div", { className: "dskm-picker-path" }, (picker.path === "__drives__" ? "此电脑" : (picker.path || "此电脑")) + (picker.count !== undefined ? "（共 " + picker.count + " 项）" : "")),
              picker.error
                ? h("div", { className: "dskm-error" }, picker.error)
                : (picker.loading
                  ? h("div", { className: "dskm-note" }, "加载中…")
                  : h("div", { className: "dskm-picker-list" },
                    picker.entries.length === 0
                      ? h("div", { className: "dskm-empty" }, "（空目录）")
                      : picker.entries.map(function (e) {
                        return e.isDir
                          ? h("div", { key: e.name, className: "dskm-picker-row", onClick: function () { pickerEnter(e.name); } },
                            h("span", { className: "dskm-picker-dir" }, "▸ " + e.name))
                          : h("div", { key: e.name, className: "dskm-picker-row dskm-picker-file" },
                            h("span", { className: "dskm-picker-file" }, e.name));
                      }))))));
        }
        return h("div", { className: "dskm-section" }, nodes);
      }

      // 当前会话的工作目录（来自客户端 sessions 服务；用于"切换会话即扫描对应项目"）
      var currentCwd = "";

      // ---- 注册设置侧边栏分区 ----
      function apply(ctx) {
        // 订阅客户端会话列表：切到任意会话（无需发言）即同步其 cwd，
        // 打开/刷新面板时随 /state 传给 host，host 据此只扫描当前项目的 skill。
        try {
          var sessionsList = ctx.sessions && ctx.sessions.list;
          if (sessionsList && typeof sessionsList.subscribe === "function") {
            var syncCwd = function () {
              try {
                var st = sessionsList.getSnapshot();
                if (st && st.current && st.byId && st.byId[st.current] && st.byId[st.current].cwd) {
                  currentCwd = st.byId[st.current].cwd;
                }
              } catch {}
            };
            sessionsList.subscribe(syncCwd);
            syncCwd();
          }
        } catch {}
        ctx.slots.inject("settings.section", function () {
          return ctx.slots.register({
            name: "settings.section",
            id: "skill-manager-ytxue",
            order: 900,
            label: "Skill 管理"
          }, SkillManagerSection);
        });
      }

      // 运行时注入声明：声明 client bundle 依赖 cordis ctx 上的 slots 与 sessions 服务。
      // 缺少 exports.inject 时，apply(ctx) 访问未声明服务会因 cordis ctx
      // Proxy 的隔离检查抛出 "cannot get property \"X\" without inject"，
      // 导致 loader entry 应用失败、插件无法启动。
      const inject = ["slots", "sessions"];

      exports.apply = apply;
      exports.inject = inject;
      return module.exports;
    }
  });

}